import React, { useState } from 'react';
import axios from 'axios';

function Login({ setUser }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://localhost:5000/api/auth/login', { email, password });
      setUser(res.data.user);
      localStorage.setItem('token', res.data.token);
    } catch (err) {
      setError(err.response?.data?.message || 'Login failed');
    }
  };

  return (
    <div className="max-w-md mx-auto mt-15 p-8 bg-white rounded-xl shadow-xl flex flex-col items-center">
      <form onSubmit={handleSubmit} className="w-full">
        <div className="text-2xl font-bold mb-6 text-gray-800 text-center">Sign In</div>
        {error && <div className="text-red-600 mb-3 text-center text-sm">{error}</div>}
        <input
          className="w-full p-3 mb-4 border border-gray-300 rounded-lg text-base bg-gray-50 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          type="email"
          placeholder="Email"
          value={email}
          onChange={e => setEmail(e.target.value)}
          required
        />
        <input
          className="w-full p-3 mb-4 border border-gray-300 rounded-lg text-base bg-gray-50 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          type="password"
          placeholder="Password"
          value={password}
          onChange={e => setPassword(e.target.value)}
          required
        />
        <button 
          className="w-full p-3 bg-gradient-button text-white font-semibold border-none rounded-lg cursor-pointer text-base hover:bg-gradient-button-hover transition-all duration-200"
          type="submit"
        >
          Login
        </button>
      </form>
    </div>
  );
}

export default Login;
